import { Pagination, type PaginationChangeDetail } from '@absoluteui/components/pagination';

const host = document.createElement('div');
document.body.append(host);
const load = (page: number, pageSize: number | null): void => {
  host.dataset.request = `${String(page)}:${String(pageSize)}`;
};
const pager = Pagination.create(host, { total: 57, pageSize: 10, pageSizes: [10, 25, 50] });
host.addEventListener('aui-change', (event) => {
  const { page, pageSize } = (event as CustomEvent<PaginationChangeDetail>).detail;
  load(page, pageSize);
});
pager.update({ total: 64 });

import { Pagination } from '@absoluteui/components/pagination';

const host = document.createElement('div');
document.body.append(host);
const pager = Pagination.create(host, { pageCount: 40, page: 12, showFirstLast: true, siblingCount: 2 });
pager.setPage(20);

import { getPageItems } from '@absoluteui/components/pagination';

const items = getPageItems(5, 10);
const text = items.map((item) => (item === 'ellipsis' ? '…' : String(item))).join(' ');
document.title = text;
